import{_ as t,a as l,b as a,c as r}from"./chunks/1819cef72bb1b3bceffd.5fDT-sri.js";import{_ as i,C as n,o as s,c as h,j as e,a as c,E as m,a5 as u}from"./chunks/framework.DNkHA0lr.js";const P=JSON.parse('{"title":"如何跻身智力前1%（完整指南）","description":"","frontmatter":{"title":"如何跻身智力前1%（完整指南）","originalTitle":"How To Join The Top 1% Of Intelligence (Full Guide)","date":"2024-10-26","originalUrl":"https://thedankoe.com/letters/how-to-join-the-top-1-of-intelligence-full-guide/","minutes":23,"sourceHash":"33d406f9d06bd2119642801a9679f1df4146821195c06936c80e9ba9d7bd694b","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-join-the-top-1-of-intelligence-full-guide/"}]]},"headers":[],"relativePath":"letters/how-to-join-the-top-1-of-intelligence-full-guide.md","filePath":"letters/how-to-join-the-top-1-of-intelligence-full-guide.md"}'),g={name:"letters/how-to-join-the-top-1-of-intelligence-full-guide.md"};function d(f,p,b,k,_,q){const o=n("ArticleMeta");return s(),h("div",null,[p[0]||(p[0]=e("h1",{id:"如何跻身智力前1-完整指南",tabindex:"-1"},[c("如何跻身智力前1%（完整指南） "),e("a",{class:"header-anchor",href:"#如何跻身智力前1-完整指南","aria-label":'Permalink to "如何跻身智力前1%（完整指南）"'},"​")],-1)),m(o),p[1]||(p[1]=u('<blockquote><p><a href="https://www.youtube.com/embed/j1Xu3qLI3r0?si=uIkWAg5PBlPTk-th" target="_blank" rel="noreferrer">观看原文视频</a></p><p>唯一真正检验智力的方式，是你能否从生活中得到你想要的东西。——纳瓦尔·拉维坎特（Naval Ravikant）</p></blockquote><p>智力是有一套科学的。</p><p>但大多数人都理解错了。他们以为智力就是书本知识和认知任务的能力。这些当然在你的成功中起作用，但故事远不止于此。</p><p>在智商测试中得分高的人，通常处于心理发展的“常规”阶段。他们几乎没有意识到（因为较低的阶段无法理解较高的阶段），自己其实仍处于真正智力（而非书本知识）的底部80%之中。</p><p>更甚者，许多“聪明”人其实孤独、贫穷、不健康，且对世界充满怨气。他们能够思考复杂的问题，却无法解决活出丰盛人生这个更大、更整体的问题。</p><p>克里斯·朗根（Chris Langan），那位智商最高的人说：“<strong>大多数高智商的人有放大倍数，却没有光圈。</strong>”换句话说，正如我们将要学到的，智商并不是智力的全部和终点。如果你的心智是一台相机，除了放大能力之外还有更多东西。</p><p>现在，如果你想拥有乔丹·彼得森（Jordan Peterson）的表达力，或者艾伦·瓦茨（Alan Watts）的思维方式，请给自己足够的时间读完这封信，去理解他们是如何达成这一成就的。</p><p>然后，至少投入1年时间来致力于自身的发展。</p><p>每天1小时用于有意识的学习和反思。</p><p>要培养这一决定你人生几乎所有成功的特质，这要求真的不算高。</p><p>驾驭自身心理健康的能力。</p><p>赚取你想要的任何金额的能力。</p><p>理解现实、并从中获得你想要的东西的能力。</p><p>这就是我们要学习的内容。</p><p>智力不能被总结成一个“5步-1分钟”的视频，所以如果你不是来读长文的，请去别处寻找你的多巴胺刺激吧。如果你能坚持读完，这封信将从根本上改变你人生的方向。</p><p>我们从哪里开始？</p><h2 id="控制论——获得你想要东西的艺术" tabindex="-1">控制论——获得你想要东西的艺术 <a class="header-anchor" href="#控制论——获得你想要东西的艺术" aria-label="Permalink to &quot;控制论——获得你想要东西的艺术&quot;">​</a></h2><blockquote><p>疯狂的定义就是重复做同一件事，却期待不同的结果——爱因斯坦</p></blockquote><p>控制论（Cybernetics）来自希腊词<em>kybernetikos</em>，意思是“操舵”或“善于掌舵”。</p><p>它也被称为“获得你想要东西的艺术”。</p><p>所以，如果纳瓦尔对智力的定义是从生活中得到你想要的东西，那么理解控制论能帮助你更快、更快地做到这一点。</p><p>控制论揭示了智能系统的特性（提示一下：你的心智就是一个系统，一个元系统）。</p><p>拥有一个目标。</p><p>朝着那个目标行动。</p><p>感知你所处的位置。</p><p>将其与目标进行比较。</p><p>再根据这个反馈重新行动。</p><p><img src="'+t+'" alt=""></p><p><em>你可以根据一个系统进行迭代、坚持试错的能力来判断其智力水平。</em></p><p>一艘偏离航线的船，会朝着目的地进行修正。一个温控器感知到温度变化并启动。胰腺在血糖升高后分泌胰岛素。</p><p>这跟从生活中得到你想要的东西有什么关系？</p><p>关系大着呢。</p><p>行动、感知、比较，以及从元视角理解系统，是高智力的基础。</p><p>高智力就是迭代、坚持并理解大局的能力。<strong>低智力的标志，是无法从自己的错误中学习。</strong></p><p>低智力的人会卡在问题上，而不是解决问题。他们碰到阻碍就放弃了。比如一个作家，未能建立读者群就放弃了，因为他缺乏尝试新事物、进行实验、找出一套适合自己流程的能力（认为不存在有效的可创建流程，这在理性上是可以被证伪的——无论你有什么限制性信念——因此这就是低智力的表现）。</p><p>高智力就是意识到，在足够大的时间尺度上，任何问题都能被解决。现实是，你可以实现你下定决心要达成的任何目标。这在理性范围内是无法被反驳的。</p><p>智力就是意识到<em>确实存在</em>一系列你可以做出的选择，这些选择会带你实现你想要的目标。你明白想法是有层级的，你不能一步从纸草纸跨越到Google文档。即使那个目标现在不可能实现，你只是暂时缺乏资源——而这些资源可能在未来几年内被发明出来——去实现那件事。</p><p>如果你想变得更有智慧，就从你正在追求的目标开始。</p><p>目标决定了系统。</p><p>目的地决定了旅程。</p><p>目标和目的地远比系统或旅程重要得多，因为它们创造了系统和旅程。</p><p>当然，你可以像尼采那样争辩说“一段旋律的终点并非其目标”，但艺术家的目标就是创作那段旋律。你所做的任何事情——从读这封信，到把眼球移动几分之一厘米，到向前迈一步，到挠一下鼻子，到打造一个十亿美元的企业——都是追求某个目标的行为，是在其路径上创造那段旋律。</p><p><em>目的地是一种视角，它让你能够欣赏这段旅程。</em></p><p>为什么人们总是一边说“一切都在于过程”，一边又在庆祝自己达成了目标？</p><p>因为你很少真正享受过程，而这没什么问题。你本来就不该享受所有的一切。你需要一点苦难，才能去欣赏那些平静的时期。如果你一直都“快乐”，那快乐就会变成常态。快乐将不再有意义。所有真正的快乐都源自于之前悲伤的视角。</p><p>换句话说，旅程和目的地是不可分割的。</p><p>当我谈论“目标”时，我并不是从典型的自助学（self-help）视角出发说的，尽管那也是一种有时值得采纳的有用视角。</p><p>我是从<em>目的论（teleology）</em>，或希腊语中的<em>kosmos（宇宙）</em>这个视角来说的——即万事万物皆服务于某个<em>目的</em>。万事万物都是更大整体的一部分。从这个意义上说，目标并非反精神性的，它们本身就<em>是</em>精神性。有限游戏与容纳这些有限游戏的无限游戏之间的关系。</p><p>当你玩一场语义游戏，拓宽像“能量”和“金钱”这样的词汇的定义时，就能发现现实的目的论特性。想想这些词的拓宽本源，以及当它们像社会中大多数情况那样被垂断或窄化时会变得多么危险。不是为了地位而设定的目标，而是那种你身边随处可见的意义。</p><blockquote><p>人天生是一个追求目标的存在。正因为人是“如此构造的”，除非他在按照自己被造就的方式去运作——作为一个目标追求者——否则他就不会快乐。因此，真正的成功和真正的快乐不仅是相伴而生的，而且彼此增强。——马克斯韦尔·马尔茨（Maxwell Maltz）</p></blockquote><p>在这个人人都在不停地反刍“新学派”灌输的“系统胜于目标！”这套说辞的世界里，目标其实远比我们想象的重要得多。</p><p>目标决定了你如何看待这个世界。</p><p>目标决定了你把什么视为“成功”或“失败”。</p><p>你可以试着“享受旅程”，但如果你追求的是错误的目标，那你就等于把享受这段旅程的难度提高了100倍。</p><p>你的心智是现实的操作系统。</p><p>那个系统是由目标构成的。</p><p>对大多数人来说，那些目标是被分配给他们的。就像被编入你心理的代码行一样被程序化。</p><p><em>去上学。找工作。被激怒。扮演受害者。65岁退休。</em></p><p>一条已知却行不通的路。</p><p>要变得更有智慧，你必须：</p><ul><li>拒绝那条已知的路</li><li>潜入未知领域</li><li>设定新的、更高的目标以拓展你的心智</li><li>拥抱混乱，允许成长发生</li><li>研究自然界的普遍规律</li><li>成为一个深度通才</li></ul><p>我们将会学习做到上述所有这些事。</p><p>过度专业化会让你始终屈从于主流范式。</p><p>人类和机器人（尤其是AI）之间的区别在于，人类创造范式。他们讲述故事。他们为项目搭建框架。而机器人只能朝着被分配给它的目标或故事去运作。</p><p>我们会在未来的一封信中讨论AI将如何改变你的生活。</p><h2 id="你的心智如何解读现实" tabindex="-1">你的心智如何解读现实 <a class="header-anchor" href="#你的心智如何解读现实" aria-label="Permalink to &quot;你的心智如何解读现实&quot;">​</a></h2><blockquote><p>内在体验的最佳状态，是意识中存在秩序的状态。这种状态发生在心理能量——即注意力——被投入到现实可行的目标中，且技能与行动机会相匹配之时。追求一个目标会给意识带来秩序，因为一个人必须把注意力集中在手头的任务上，暂时忘记其他一切。——米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>心智为了生存有两个关键目的：</p><ol><li>实现已知的目标</li><li>发现未知的目标</li></ol><p>心智是一台信息处理与模式识别的机器，我们根据自身的发展水平，对它拥有一定程度的控制权。</p><p>心智是一个系统——包含着一整套复杂的子系统——它会接受、拒绝并利用信息，来助力你喂给它的那些目标。</p><p>如果你总是聚焦于负面结果，它们就会成为现实，而你会把生活中的不幸归咎于除自己之外的每一个人。</p><blockquote><p>一个把自己认定为“失败型人物”的人，即便机会掉进他怀里，他也会不顾一切良好意图，找到某种方式去失败。一个自认为是不公正的受害者、“天生就该受苦”的人，也总能找到情形来验证自己的看法。——马克斯韦尔·马尔茨（Maxwell Maltz）</p></blockquote><p>换句话说，如果你认为自己能做到，你就能做到；如果你认为自己做不到，你就做不到。</p><p>在你心智的根部，如同一个操纵木偶的幕后玩偶师，是你的身份认同或自我（ego）。</p><p>你的自我是一套塑造你视角的观念、信念、价值观和标准体系。与流行的看法相反，自我并不是敌人。它是讲故事的人，是解读者。你的任务不是摆脱它，而是去发展它、去拓展它，去移除那些将你困在狭隘视角中的、使生活变得被动而消极的、被条件化限定的边界。</p><p>你的视角就像相机的镜头。</p><p>你可以放大和缩小。</p><p>你可以聚焦于场景的一部分——同时使背景模糊——或者聚焦于整个场景的细节。</p><p>你的视角会影响你对各种情境的感知。</p><p>这意味着，你的身份认同将限制它所能感知到的信息，如果它接收到不符合自身信念、价值观或标准的信息，就会将其拒之门外。</p><p>你的心智会自动接受和拒绝那些有助于实现被编程进你脑中的目标的信息。</p><p>如果你想找一份工作，多巴胺会向你标示出那些有助于你获得那份工作的信息和机会的重要性。</p><p>你书中的标注会反映那个目标。你（跟任何人）交谈的方式会反映那个目标。你在社交媒体上互动的内容会反映那个目标（而算法会通过给你展示更多此类信息，无论好坏，来帮助这种身份认同的根基进一步深化）。</p><p>如果你想辞掉工作，多巴胺也会做同样的事。就像猎人会注意到灌木丛上新长出的浆果一样，多巴胺会标示出那些对你脑海中首要目标的“生存”至关重要的信息，因此你更有可能记住并利用那些信息。</p><p>你的 Google 搜索会从“2024 年最适合从事的职业”变成“2024 年最适合开始的生意”。</p><p>或者，你会更想去看看 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>，在那里我帮你拆解你的身份认同，把它变成一个能盈利的一人企业。</p><p>即便是像小说这样的书，你划的重点也会和抱有不同目标的人截然不同。</p><p>无论我们是否意识到，我们都在强化那个可能平庸的身份认同，而它决定了我们人生的结果。对大多数人来说，这个结果会是负面的。</p><h3 id="你的大脑是一个控制论系统" tabindex="-1">你的大脑是一个控制论系统 <a class="header-anchor" href="#你的大脑是一个控制论系统" aria-label="Permalink to &quot;你的大脑是一个控制论系统&quot;">​</a></h3><p><strong>社会是一个行为系统。</strong></p><p>而在你学会理解你所说的语言的那一刻，社会就往你脑子里灌输了三个大目标。</p><ol><li><p>上学</p></li><li><p>工作</p></li><li><p>退休</p></li></ol><p>99% 的人只是以一种能通向这些目标的方式来解读日常情境。他们为了地位和生存而学习别人要求他们学的东西，从而把心智关闭在真正重要的人生事物之外。他们变成了专业化的奴隶，依赖那些需要这种特定知识的人。他们没有那种深厚且泛化的技能组合，无法走出属于自己的路。一个只学习写作的作家没有机会赚到独立的收入。</p><p>99% 的人在不知不觉中就在练习那些技能、集中注意力、给大脑编程去过平庸的人生，因为他们从未质疑，也从未反抗。</p><p><strong>一个人们常常太晚才明白的道理：</strong></p><p>成功不是被计划出来的，它是自动发生的。</p><p>成功的人——无论他们是否意识到——他们的大脑早已被编程去实现那些通向成功的目标。他们透过自己目标的视角看待人生，这让他们把<em>正确</em>的信息储存进潜意识，从而影响他们的选择，这些选择日积月累最终达成了那个目标。</p><p>你的身份认同、视角、以及你对情境的感知，都是彼此依次输入并相互强化的系统。</p><p><strong>过上你想要的人生，80% 归结于创造属于你自己的目标，而大多数人只是社会目标的无脑奴隶。</strong></p><p>目标改变你解读情境的方式，这影响你的行动，行动又编程你的身份认同，日积月累，多年后就复合成一种富足的人生。</p><p>除非一个问题影响到某个目标，你根本无法意识到它的存在。</p><p>除非你意识到问题，你无法解决它。</p><p>大多数人没有目标。大多数人害怕犯错。大多数人从不给自己机会去改善生活的任何一个方面。</p><p>如果你不为一个目标投入精力，你就不会感受到没达成那个目标的痛苦。</p><p>偶尔的、远未到酗酒程度的喝酒本来不是问题，直到它妨碍了我夏天减重和写书这两个目标的实现。</p><p>在我有这些目标之前，我从未把它看作问题。哪怕只是一晚适度饮酒，我的晨跑也会受影响。我会脱水、缺乏动力。我的写作也会因大脑昏沉而受损。每一天没能朝目标前进，都变得越来越痛苦，直到我最终决定戒掉那个“坏”习惯。而到了那个时刻，戒掉这个习惯毫无阻力。</p><p>重点在于：问题之所以成为问题，是因为你有一个与之对应的目标。如果你没有任何值得追求的目标，你就<em>看不见</em>那一大堆问题——而一旦解决它们，就能带来更好的生活。</p><p>大多数人对自己想从那个目标中得到什么并没有清晰的愿景，所以他们行为带来的负面影响也就被忽视了。</p><p>你的坏习惯之所以看起来不值得戒掉，是因为你没有（或者没有优先考虑）那些值得你百分百投入的责任。</p><p>如果那些责任的重要性超过了你坏习惯带来的快感，你会毫不犹豫地停下来。</p><p>目标与身份认同是交织在一起的。</p><p>人类是靠概念层面生存的。</p><p>当那些构成“我们是谁”的东西受到威胁时，我们会感到受威胁。</p><p>一个健美运动员在处于一个对训练和饮食控制力较弱的环境中时，会感到压力和痛苦。</p><p>一套routine（日常惯例）就是一组用来梳理心智的实用目标。一个搬到新地方或长期出差旅行的作家，会经历一段压力很大的适应期，直到他的大脑运行在新的系统上。如果他们在正常routine之外无法好好写作，他们就会感到受威胁，因为“他们是谁”这件事可能会消亡。</p><p>如果你用新的刺激（持续的自我教育）来训练自己，直到你的身份认同变成一种“如果不达成新目标就无法生存”的状态——你就会不可避免地轻松实现这些目标，无论它们是什么。如果你想要一份成功的事业、一段关系，或任何超出常规的东西，你必须通过改变“你是谁”，从根本上改变你大脑所运作的目标。</p><p>要改变你是谁，你必须去学习、去实践、去体验新的信息，从而重新给你大脑那被社会植入的错误线路编程。</p><h2 id="心理发展的各个阶段——迈入那顶尖的-1" tabindex="-1">心理发展的各个阶段——迈入那顶尖的 1% <a class="header-anchor" href="#心理发展的各个阶段——迈入那顶尖的-1" aria-label="Permalink to &quot;心理发展的各个阶段——迈入那顶尖的 1%&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>正如爱因斯坦（Albert Einstein）据传说过、但其实并没说过的那句话：</p><blockquote><p>你无法用制造问题时的那个意识层次去解决那个问题。</p></blockquote><p>如果你想变得更聪明，你需要拓展你的心智去看到更大的图景。去讲述一个更全面的故事。去从所有的视角看待情境。不要让自己的思考被砍头——不要屈从于某一个视角——某一种宗教、某一种商业模式、某一个研究领域——那些东西因为其单一维度性而可以被验证为非真理。</p><p>当你有一个更高的目标时，你就能朝着那个目标更聪明地思考。</p><p>但你无法一瞬间就拓展到更高层次的心智。</p><p>事实上，要达到最高阶段需要花费一生的时间（谁知道当科技让我们能活到 500 岁时，人类的发展还能走多远呢？别死了。）</p><p>我们将结合我们对智力的定义，来剖析自我发展理论（Ego Development theory）。就本文而言，更高的阶段等同于更高的智力。</p><p>这一理论还有更多细微之处。我建议你去阅读<a href="http://onesystemonevoice.com/resources/Cook-Greuter+9+levels+paper+new+1.1$2714+97p$5B1$5D.pdf" target="_blank" rel="noreferrer">苏珊娜·库克-格鲁特（Susanne Cook-Greuter）的完整研究论文</a>。我也建议你进一步探索“螺旋动力学”（Spiral Dynamics）和肯·威尔伯（Ken Wilber）的 AQAL 模型等概念，来完善你对这一切的理解。</p><p>我们将在本文中提取与我们使用场景相关的信息。</p><p>在自我发展理论（EDT）中，有三个运动方向：</p><ol><li><strong>横向</strong> —— 在同一阶段内的横向扩展。发展新技能、增加信息和知识。</li><li><strong>纵向上升</strong> —— 转变。成长到一个新的阶段和视角。</li><li><strong>纵向下降</strong> —— 由于生活状况、环境、压力和疾病导致的暂时或永久性退步。</li></ol><p>横向发展是在填满一个人的杯子。</p><p>纵向发展是在扩大杯子的尺寸。</p><p>一个有趣的事实：仅仅压力本身就可以让你退回到更低的发展阶段。这也常常是为什么我们在压力下会变得更狭隘、更反应式，但如果你达到了更高的基线发展阶段，压力就不会把你拉得那么低。也就是说，最低点会更高一些。</p><p><img src="'+a+'" alt=""></p><p>上面这张来自 <a href="https://www.sloww.co/horizontal-vertical-development/" target="_blank" rel="noreferrer">Sloww</a> 的图展示了螺旋动力学（Spiral Dynamics，另一种人类发展模型）的阶段颜色。值得注意的是，发展是以螺旋的形状发生的。你常常会发现自己好像又绕回到了人生中一个类似的阶段，但带着新的视角。它也代表了个体化（individuation）和整合（integration）的循环。</p><p>我们的目标是达到新的纵向发展阶段，而不是被困在横向发展的老鼠赛跑之中。</p><p>发展新技能、获取新知识当然很棒。从很多方面来说，这些都是成长所必需的，但它们并不能带来通往新的心智层次的成长，从而带来智力的提升，以及获得你真正想要的东西（因为“你想要的东西”也在不断进化）。</p><p>要达到新的发展阶段，需要你的视角发生进化。你需要：</p><ul><li>在该阶段积累时间、理解力和横向发展。新的技能、挑战与目标。</li><li>有意识地、以开放的心态去探索一种与自己不同的视角。</li><li>通过教育和有意识的训练，从根本上改变你是谁；致力于更深层的理解和对真理的追求。</li><li>控制论式的试错。设定一个存在于新发展阶段的目标，用朝向那个目标的方式去解决问题，并在意识到自己没有解决对的问题时进行自我修正。</li></ul><p>痛苦有时是达到新视角的必要催化剂。就像当你对自己所处的境地感到厌恶到极点时，你才终于突破到一个新的层次。一个新的视角浮现出来，你也随之进化。</p><p>理解下面这些阶段，可以彻底改变你人生的方向。</p><p>一旦你意识到它们，你就可以努力去逐一推进。</p><h3 id="前常规阶段——占人口的-5" tabindex="-1">前常规阶段——占人口的 5% <a class="header-anchor" href="#前常规阶段——占人口的-5" aria-label="Permalink to &quot;前常规阶段——占人口的 5%&quot;">​</a></h3><p><img src="'+r+'" alt=""></p><p>你们大多数人都不处在这些阶段，所以我们会简短说明。</p><p>前常规阶段——<em>共生（symbiotic）、冲动（impulsive）、机会主义（opportunist）</em>——以自我中心主义为特征。</p><p>大部分人在出生到大约 10 岁之间会经历这些阶段的发展。</p><p>自我与他人之间缺乏区分。需求集中在生存、个人欲望和即时满足上。而到这些阶段的尾声，我们开始理解到有一些社会规则需要我们去接受和遵守。</p><h3 id="常规阶段——占人口的-75-80" tabindex="-1">常规阶段——占人口的 75-80% <a class="header-anchor" href="#常规阶段——占人口的-75-80" aria-label="Permalink to &quot;常规阶段——占人口的 75-80%&quot;">​</a></h3><p>我们可以把常规阶段理解为猴子模仿其他猴子，试图获得地位、成为食物链顶端的过程。</p><p>大多数高智商人群都停留在这个阶段。</p><p>请注意，这些阶段并没有哪个比哪个“更差”。它们只是“更低”而已。每个人都必须经历每一个阶段。问题在于被困在其中任何一个阶段里，而这在社会中是非常容易发生、也非常容易观察到的现象。</p><p>当你和处于常规阶段的人交谈时，你往往是在和一台电视机或一个 YouTube 频道对话，而不是在和一个独特的个体对话。这在当下的政治场域中相当普遍。</p><p><strong>第三阶段）从众者（Conformist）</strong></p><p>他们的身份认同由他们与某个群体的关系来定义。</p><p>专注于人气的高中生。严格遵守规则的公司员工，比如必到场参加所有强制性会议。军队或宗教式的严格恪守。</p><p>换句话说，从众者服从权威，并顺从群体。这在“抱着圣经不放的人”身上最容易看到——这些人从不质疑他们从小被灌输的宗教意识形态。（<strong>记住</strong>：如果你出生在世界的另一边，你就不会是基督徒、天主教徒、穆斯林等等。这一点无可争辩。）</p><p><strong>第三/四阶段）专家（Expert）</strong></p><p>专家阶段的特征是自我创作（个人成长）、处理复杂问题、自我反思，以及复杂的问题解决能力。</p><p>专业人士活在这个阶段。工程师类型。以技能为中心。他们是科学唯物主义者,认为一切都可以用现代科学解释。</p><p>他们擅长完成任务,却不擅长判断自己是否在做正确的任务。他们看不出自己所做的事对人类是否重要。</p><p>他们是“无所不知者”。他们知道一切,并认为一切都该按他们的方式来做。</p><p><strong>第四阶段:成就者</strong></p><p>西方教育和学校教育大多是为了培养成就者。</p><p>这是一个人在思维上所能达到的顶峰阶段。它是西方式成功的定义。</p><p>这里发生了从雇员心态到创业者心态的转变。从个人技能转向这项技能如何在社会中被运用。</p><p>在我们这个领域,这是社交媒体上大多数人的主导特征。自我提升和商业阶段。Hamza、Hormozi以及其他自我提升、商业或男子气概类创作者,都是成就者的例子,他们偶尔会窥见后传统阶段的一角。比如当他们读《优越男人之道》(The Way Of The Superior Man)时,却仍是透过成就者的视角去解读它。</p><p>这就是为什么我常常用能吸引处于成就者阶段的人的YouTube标题。比如谈论如何赚很多钱。他们是我的目标受众。我想把他们引向发展的下一阶段,让他们逐渐接触灵性和其他更深层的话题。而且,网上这类人数量不少,这也有帮助。</p><h3 id="后传统阶段——占人口的15-20" tabindex="-1">后传统阶段——占人口的15-20% <a class="header-anchor" href="#后传统阶段——占人口的15-20" aria-label="Permalink to &quot;后传统阶段——占人口的15-20%&quot;">​</a></h3><p>每个阶段都有不同的目标和世界观。</p><p>也就是说,他们对成功的理解在演化,<em>因此他们心智所运行的系统也随之演化</em>。如果我们认为高效的系统是“有序的”,那我们就能理解为什么混乱、不适和痛苦是发展的一部分。</p><p>如前所述,传统阶段就像猴子模仿其他猴子(当然,稍微发展一点)。但那不是智力。</p><p>智力是你解决问题的能力,因为你无法用创造问题的那个心智去解决问题。你必须扩展。所以,如果你卡在一份你厌恶的工作或其他事情里,却没有通过扩展视角来解决问题,那你就不是聪明的。</p><p>智力是质疑你的信念,认识到深层的普遍模式,并理解真理的矛盾之处——唯一的绝对真理就是没有绝对真理。</p><p>后传统阶段是我们开始接触系统思维的地方。整体大于部分之和。现实更像一个有机体,而不是可以被拆解和研究的机器。</p><p>第一梯队(传统)思维和第二梯队(后传统)思维之间的巨大跨越正是如此。它是多视角的。它不仅仅关乎你的商业模式、自我提升意识形态或宗教。你开始注意到构成它们所有的<em>属性</em>。比如基督教和佛教如何指向同一个现实的本质(神),尽管它们表面上会否认这一点,因为较低阶段无法理解较高阶段,而较高阶段却能理解较低阶段。当然,非意识形态化的佛教徒是另一回事,但大多数嬉皮士只是盲目采纳那些信念,却没有真正理解。</p><p>在这些阶段,你开始收集更多的视角。你在这座山上站得越高,就越能看到通往你所在之处的多条路径。你就越想帮助人们走一条更好的路。</p><p><strong>第四/五阶段:多元论者</strong></p><p>第四人视角被发现了。</p><p>多元论者开始跳出他们成长于其中的体系——现状——并质疑自己的信念和价值观。</p><p>最常见的例子是一个嬉皮士,幻想着每个人都变成嬉皮士。但他们还看不到别人所经历过的发展,所以那个愿景是站不住脚的。</p><p>可以把这想象成从《圣经》狂热信徒到无神论者再到第一次发现灵性的嬉皮士的演化,但他们还没有回过头去整合《圣经》狂热信徒身上的真理。</p><p>现在,想象一下这种情况发生在多个领域,比如工作中,人们从企业打工人变成创业者再变成穷困的艺术家,却还没意识到他们可以做自己热爱的事,并借此过上不错的生活,同时为人类做出贡献——这正是我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学</a>中试图教授的东西,通过在传统与后传统之间架起桥梁。</p><p>(这些说法并不完全准确,但作为例子还是很好用的。)</p><p><strong>第五阶段:策略家</strong></p><p>我对策略家阶段有很强的共鸣。</p><p>它占据了我过去几年生活中的很大一部分(从我能判断的来看,我可能是自欺欺人、发展不足。我对此持开放态度)。</p><p>策略家意识到直觉比逻辑和理性(存在于传统阶段中)更强大。认为某件事已经被正式证明,这种想法很可笑,几乎不可能做到。</p><p>探索和发现开始变得比实现某个目标或赚很多钱更重要——而这往往反而能带来更多目标的实现和更多的财富。</p><p>策略家对世界在进化过程中需要什么才能前进有一种愿景,并理解现实的普遍原则。</p><p>策略家是价值创造者。他们主要关注自我发展、他人发展、自我实现、整合以及拥有自己的阴影面。真理可以被逼近,但更高的视角更好(更高的视角)。</p><p><strong>第五/六阶段:构念觉知者</strong></p><p>在我看来,乔丹·彼得森(Jordan Peterson)<em>大部分</em>落在构念觉知者和策略家阶段之间。就宗教而言,以及他对基督教的加倍坚持,他仍然带有传统阶段的阴影,除非他是在利用这一点作为一种手段,帮助更多人从那些阶段发展出来,这也完全有可能是真的。</p><p>如果心智是一台电脑,构念觉知者会明白:</p><ul><li>传统阶段只是在这台电脑上玩一个应用或一个视频游戏。他们只停留在一个网站或一个浏览器上。</li><li>后传统阶段开始能够浏览整个桌面。他们可以玩最有意义的游戏,甚至能创造自己的游戏。</li></ul><p>构念觉知者进入了思维的第五维度,即认知维度。他们能看到心智如何构建现实和意义。他们能看到大多数人在某个视角中找到安慰,但他们自己却无法从这些视角之外,放大到一个更大的整体来看待。</p><p>这时,现实的普遍原则真正开始融会贯通。统一与分裂,创造与毁灭,熵与财富。他们开始从一个新的、抽象的层面来思考世界,而这可能带给他们痛苦,因为他们不断在与这个问题作斗争:“所以呢?这种所谓的精神自嗨到底能怎样帮到我?”</p><p>答案是:更全面的决策能力。</p><h3 id="智力顶端的1-——超越阶段" tabindex="-1">智力顶端的1%——超越阶段 <a class="header-anchor" href="#智力顶端的1-——超越阶段" aria-label="Permalink to &quot;智力顶端的1%——超越阶段&quot;">​</a></h3><p>终于,来到智力顶端的1%。</p><p>合一阶段。</p><p>在这里,神秘主义者听起来更像是自欺欺人,而不是富有洞察力。</p><p>而那些真正有洞察力的人,比如艾伦·瓦茨(Alan Watts)和特伦斯·麦肯纳(Terrence McKenna),有一种能力,能用简单而深刻的句子描述现实,从而缓解你的忧虑。</p><p>他们连接到了源头。无限的智慧。</p><blockquote><p>现实现在通常被体验为未分化的现象学连续体,或统一意识的创造性根基。每一个物体、词语、想法、感受和感觉,每一种理论,都被理解为一种人为构造:分割出来,创造出本不存在的边界。追求意义与联结是人类境况中不可或缺的一部分。给经验命名并做出区分,对于人类的成长、研究、互动和交流是必要的,但在源头上,并没有什么东西可以区分。——苏珊娜·库克-格鲁特尔(Susanne Cook-Greuter)</p></blockquote><p>要达到这个发展阶段,你无法强求。你必须经历所有其他阶段,而从你开始摆脱从众思维的旅程算起,这可能需要十年,甚至三十年。</p><p>反抗你被教导视为绝对真理的信念,那一天,才是你真正诞生的日子。</p><p>但是,理解这个阶段的主要特征确实有帮助,这样你就能识别出它们并以此为目标。有了这种意识,你就能识别出自己决策中的错误,并努力纠正它们。</p><p>合一阶段的特征:</p><ul><li>真理内在于宇宙之中,但无法通过逻辑或理性去把握。</li><li>他们采用一种宇宙性或普世性的视角作为组织原则,以及一个稳固的立足点,由此衍生出意义。</li><li>大多数关于觉悟的定义都已实现。他们以一种全新的、彻底开放的方式来消化经验。</li><li>他们理解自我(ego)需要存在以求生存,同时也认识到追求永恒的欲望是一种幻觉。<em>自我在需要时可以作为一种视角或透镜派上用场。</em></li><li>二元对立与冲突被见证,而不带任何紧张感或想要改变它们的欲望。</li><li>他们生活在一个创造性的根基之中,并倾向于持续的人性,完成他们进化的命运。</li><li>生命被视为一种暂时的、有时是自愿的分离(菩萨式的),脱离他们所植根的那个“创造性根基”。</li><li>他们并不像传统嬉皮士所设想的那样被动。相反,这种非个人化的立场,让他们在需要时能够采取更有意识、更有力、更直接的行动。</li></ul><p>换句话说,嬉皮士和合一者之间存在着显著的差异。</p><p>嬉皮士试图与世界分离,并否认自我(ego)。</p><p>合一者大部分时间处于一种分离的状态,但他们明白,进入相对世界对于大多数工作、社会互动和进化来说都是必要的。</p><p>总结一下,智力并不在于书本知识或放大细节的能力。</p><p>它关乎的是整体性的模式识别和视野的开阔度。你能否将视角拉远到所有边界和限制都消融的程度。</p><p>通过有意识的发展,并保持一种觉察——知道自己何时正在把自己封闭起来、拒绝成长,并陷在某个阶段中——你就能到达合一阶段。</p><p>事实上,我的书,<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》</a>(The Art Of Focus),试图涵盖通往这些更高发展阶段的大部分路径。至少那是我的尝试。</p><p>感谢你的阅读。</p><p>我希望这个话题对你而言,能像它对我一样深刻而具有转变性。</p><hr><p><a href="/en/letters/how-to-join-the-top-1-of-intelligence-full-guide">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',222))])}const x=i(g,[["render",d]]);export{P as __pageData,x as default};
